        "tags": ["Auth"],
        "summary": "Get EIP-712 nonce for wallet authentication",
        "operationId": "getAuthChallenge",
        "security": [],
        "parameters": [
          {
            "name": "wallet_address",
            "in": "query",
            "required": true,
            "description": "Ethereum wallet address (0x...)",
            "schema": {
              "type": "string",
              "pattern": "^0x[a-fA-F0-9]{40}$"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Challenge nonce generated (5 minute TTL)",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "nonce": { "type": "string", "description": "Random 32-byte hex nonce" },
                    "expires_at": { "type": "string", "format": "date-time" },
                    "sign_this": {
                      "type": "object",
                      "properties": {
                        "domain": {
                          "type": "object",
                          "properties": {
                            "name": { "type": "string", "example": "WORQ" },
                            "version": { "type": "string", "example": "2" },
                            "chainId": { "type": "integer", "example": 8453 }
                          }
                        },
                        "types": { "type": "object" },
                        "value": {
                          "type": "object",
                          "properties": {
                            "wallet": { "type": "string" },
                            "nonce": { "type": "string" },
                            "timestamp": { "type": "integer" }
                          }
                        },
                        "message": { "type": "string" }
                      }
                    }
                  }
                }
              }
            }
          },
          "400": { "$ref": "#/components/responses/BadRequest" },
          "429": { "$ref": "#/components/responses/RateLimited" }
        }
      }
    },
